UPDATE sys_login_record SET ended_at=#{now}, end_reason=#{reason}
, last_activity_at=#{now}
WHERE id=#{id} AND end_reason IS NULL

UPDATE sys_login_record SET ended_at=#{now}, end_reason=#{reason}
WHERE user_id=#{userId} AND end_reason IS NULL
  AND absolute_expires_at > #{now}
  AND TIMESTAMPADD(SECOND, idle_timeout_seconds + activity_interval_seconds, last_activity_at) > #{now}
